const tabs = phi.tabs.list();
const depot = tabs.find(t => t.url.includes('jamaica-bus-depot') && t.drivable !== false);
if (depot) phi.tabs.switch(depot.tabId);
phi.narrate("trying to pull the actual words out of the PDF report");
const out = phi.js(async () => {
  function loadScript(src) {
    return new Promise((res) => {
      const s = document.createElement('script');
      s.src = src;
      s.onload = () => res('ok');
      s.onerror = () => res('fail');
      document.head.appendChild(s);
      setTimeout(() => res('timeout'), 8000);
    });
  }
  const status = await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js');
  if (!window.pdfjsLib) return { status, lib: false, url: location.href };
  return { status, lib: true, url: location.href };
});
return out;

const tabs = phi.tabs.list();
const pdfTab = tabs.find(t => t.url.includes('document/10341')) || tabs[0];
phi.tabs.switch(pdfTab.tabId);
phi.narrate("reading the first pages of the PDF itself");
const out = phi.js(async () => {
  function loadScript(src) {
    return new Promise((res) => {
      if (window.pdfjsLib) return res('cached');
      const s = document.createElement('script');
      s.src = src; s.onload = () => res('ok'); s.onerror = () => res('fail');
      document.head.appendChild(s);
      setTimeout(() => res('timeout'), 8000);
    });
  }
  const st = await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js');
  if (!window.pdfjsLib) return { st, lib: false };
  try { pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js'; } catch(e) {}
  const res = await fetch(location.href, { credentials: 'include' });
  const buf = await res.arrayBuffer();
  const doc = await pdfjsLib.getDocument({ data: buf }).promise;
  const pages = [];
  const n = Math.min(3, doc.numPages);
  for (let i = 1; i <= n; i++) {
    const p = await doc.getPage(i);
    const tc = await p.getTextContent();
    pages.push(tc.items.map(it => it.str).join(' ').replace(/\s+/g, ' ').slice(0, 900));
  }
  const meta = await doc.getMetadata().catch(() => null);
  return { st, lib: true, numPages: doc.numPages, status: res.status, bytes: buf.byteLength, info: meta && meta.info ? { Title: meta.info.Title, Author: meta.info.Author, Subject: meta.info.Subject } : null, pages };
});
return { tabUrl: pdfTab.url, out };

const tabs = phi.tabs.list();
const summary = tabs.map(t => ({ id: t.tabId, url: t.url.slice(0,120), title: (t.title||'').slice(0,90), drivable: t.drivable }));
const depot = tabs.find(t => t.url.includes('jamaica-bus-depot'));
let docLinks = null;
if (depot) {
  phi.tabs.switch(depot.tabId);
  const q = phi.query('a', { fields: ['href'], limit: 300 });
  docLinks = q.items.map(i => i.href).filter(h => h && /document|\.pdf/i.test(h));
}
const nt = phi.tabs.open('https://new.mta.info/document/10341');
return { summary, docLinks, newTab: nt };

